-- Snapshot of the complete 15-category public Cat Parts Store navigation plus verified first-page product references.
-- Category counts are the counts displayed on Cat pages when captured (2026-11-23), not a claim that every SKU has been imported.
create table if not exists public.cat_part_categories (
  category_key text primary key,
  name text not null,
  parent_key text references public.cat_part_categories(category_key) on delete cascade,
  source_url text not null,
  source_count integer,
  is_active boolean not null default true,
  source_name text not null default 'Cat Parts Store (official)',
  captured_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists cat_part_categories_parent_idx on public.cat_part_categories(parent_key);
revoke all on public.cat_part_categories from public, anon, authenticated;
grant select on public.cat_part_categories to service_role;
on conflict(category_key) do update set name=excluded.name,source_url=excluded.source_url,source_count=excluded.source_count,is_active=true,updated_at=now();
on conflict(category_key) do update set name=excluded.name,parent_key=excluded.parent_key,source_url=excluded.source_url,source_count=excluded.source_count,is_active=true,updated_at=now();

on conflict(part_number) do update set
 name=excluded.name,description=excluded.description,technical_group=excluded.technical_group,
 source_name=excluded.source_name,source_url=excluded.source_url,source_note=excluded.source_note,
 verification_status='REFERENCE',image_url=excluded.image_url,specifications=excluded.specifications,
 compatible_models=excluded.compatible_models,updated_at=now();
